from fastapi import FastAPI, Body, Request
from fastapi.testclient import TestClient
from fastapi.exceptions import RequestValidationError
import pytest

app = FastAPI()

@app.post("/strict")
async def strict_endpoint(payload: dict = Body(..., strict_content_type=True)):
    return payload

@app.post("/non-strict")
async def non_strict_endpoint(payload: dict = Body(..., strict_content_type=False)):
    return payload

client = TestClient(app)

def test_strict_content_type_success():
    response = client.post("/strict", json={"foo": "bar"})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_strict_content_type_missing_header():
    # TestClient.post(json=...) sets content-type to application/json
    # To test missing header, we use content=... and headers={}
    import json
    response = client.post(
        "/strict", 
        content=json.dumps({"foo": "bar"}), 
        headers={}
    )
    assert response.status_code == 422
    assert response.json()["detail"][0]["loc"] == ["header", "content-type"]

def test_strict_content_type_wrong_header():
    import json
    response = client.post(
        "/strict", 
        content=json.dumps({"foo": "bar"}), 
        headers={"content-type": "text/plain"}
    )
    assert response.status_code == 422
    assert response.json()["detail"][0]["loc"] == ["header", "content-type"]

def test_non_strict_content_type_missing_header():
    import json
    response = client.post(
        "/non-strict", 
        content=json.dumps({"foo": "bar"}), 
        headers={}
    )
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_non_strict_content_type_wrong_header():
    import json
    response = client.post(
        "/non-strict", 
        content=json.dumps({"foo": "bar"}), 
        headers={"content-type": "text/plain"}
    )
    # In non-strict mode, if it's not application/json, it should be treated as body_bytes
    # But since we are using a dict as payload, it will fail validation if it's not JSON
    # Wait, if it's not application/json, it's passed as body_bytes to _validate_value_with_model_field
    # If the annotation is dict, it will fail.
    assert response.status_code == 422
    # The error should be about the body, not the header
    assert response.json()["detail"][0]["loc"] == ["body"]

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

